import { supabase } from './client'

export type AppRole = 'super_admin' | 'tenant_admin' | 'user'

export const rolesService = {
  async getMyRoles(): Promise<AppRole[]> {
    const { data, error } = await supabase
      .from('user_roles')
      .select('role')
    if (error) {
      // Table may not exist yet (migration not run) — fail soft.
      console.warn('[roles] getMyRoles failed:', error.message)
      return []
    }
    return (data ?? []).map((r) => r.role as AppRole)
  },

  async hasRole(role: AppRole): Promise<boolean> {
    const roles = await this.getMyRoles()
    return roles.includes(role)
  },
}
